import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS,T,en,fin,DUR,interpolate,clamp,Easing,FONT,Textura,Profundidad,Camara,Paso,seguir,enCamino,tono,h,golpe,sacudida,Contador,Chip,Destello} from './kit';
export const SUBS={arriba:230,acento:'#E7FF00'};

// Inicio de cada escena E1..E13 (primera palabra de cada una).
const A=[0,7,20,29,39,50,63,77,91,115,127,138,150].map(T);
const L='#E7FF00',VIO='#8e5be0',ARE='#e6c38b',ROS='#ff6f91',HUE='#f7f1e1',VIE='#cdb88f',PIE='#8b8e93',OUT='#3b3326',CREMA='#f4e4c4';
const q=(s:number,a:number,b:number,e:(x:number)=>number=Easing.inOut(Easing.cubic))=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:e});
const beat=(s:number,f=6.5)=>Math.pow(Math.max(0,Math.sin(s*f)),6);
// Esqueleto en coordenadas mundo: centro (540,1010), escala .95
const sk=(x:number,y:number):[number,number]=>[540+.95*x,1010+.95*(y-110)];

// ---------- piezas dibujadas ----------
const Defs=()=> <defs>
 <radialGradient id='gV' cx='.35' cy='.3' r='.8'><stop stopColor='#d9c4ff'/><stop offset='.55' stopColor='#8e5be0'/><stop offset='1' stopColor='#4b2a8a'/></radialGradient>
 <radialGradient id='gO' cx='.35' cy='.3' r='.8'><stop stopColor='#fff3d6'/><stop offset='.55' stopColor='#e6c38b'/><stop offset='1' stopColor='#a9803e'/></radialGradient>
 <linearGradient id='sp' x1='900' y1='0' x2='1300' y2='0' gradientUnits='userSpaceOnUse'><stop stopColor='#070b26' stopOpacity='0'/><stop offset='1' stopColor='#070b26'/></linearGradient>
 <radialGradient id='tierra' cx='.4' cy='.3' r='.8'><stop stopColor='#7cc4ff'/><stop offset='.6' stopColor='#2a67c4'/><stop offset='1' stopColor='#0f2a63'/></radialGradient>
 <linearGradient id='visor' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#1b2447'/><stop offset='.5' stopColor='#3b5fa8'/><stop offset='1' stopColor='#0c1230'/></linearGradient>
</defs>;

const Tag:React.FC<{x:number;y:number;k?:number;width?:number;color?:string;size?:number;children:React.ReactNode}>=({x,y,k=1,width=420,color=L,size=36,children})=><g transform={`translate(${x} ${y}) scale(${k})`} opacity={Math.min(1,k*2)}><rect x={-width/2} y={-40} width={width} height={80} rx={18} fill='#1b2231' stroke={color} strokeWidth={4}/><text textAnchor='middle' y={13} fill={color} fontWeight={800} fontSize={size} fontFamily={FONT}>{children}</text></g>;

const Luz:React.FC<{x:number;y:number;r:number;color:string}>=({x,y,r,color})=><circle cx={x} cy={y} r={r} fill={color} style={{filter:`blur(${r*.3}px)`}}/>;
const Anillo:React.FC<{x:number;y:number;t0:number;s:number;c?:string;r?:number}>=({x,y,t0,s,c='#fff',r=380})=>{const t=s-t0;if(t<0||t>.7)return null;const R=40+t*r;return <ellipse cx={x} cy={y} rx={R} ry={R*.3} fill='none' stroke={c} strokeWidth={6} opacity={1-t/.7}/>;};

// Célula: 'd' demoledora (violeta, boca que mastica) / 'o' obrera (arena con casco lima)
const Cel:React.FC<{x:number;y:number;r?:number;t:'d'|'o';s:number;f?:number;act?:number;hero?:boolean;dormido?:boolean;tool?:boolean}>=({x,y,r=60,t,s,f=0,act=1,hero=false,dormido=false,tool=true})=>{
 const R=hero?r*1.25:r;const b=Math.abs(Math.sin(s*5+f))*act;const sq=1+.07*Math.sin(s*10+f)*act;
 const ol=t==='d'?'#3d2278':'#8f6a2e';const mo=.5+.5*Math.sin(s*9+f);
 const ojo=(ox:number)=>dormido?<path key={ox} d={`M${ox-R*.15} 0Q${ox} ${R*.12} ${ox+R*.15} 0`} stroke='#241a35' strokeWidth={5} fill='none' strokeLinecap='round'/>:<g key={ox}><ellipse cx={ox} cy={-R*.04} rx={R*.17} ry={R*.22} fill='#fff'/><circle cx={ox+R*.03} cy={-R*.01} r={R*.1} fill='#241a35'/><circle cx={ox-R*.01} cy={-R*.07} r={R*.045} fill='#fff'/></g>;
 return <g transform={`translate(${x} ${y-b*R*.45})`}>
  <ellipse cx={0} cy={R*1.0+b*R*.45} rx={R*.8} ry={R*.16} fill='rgba(0,0,0,.28)'/>
  <g transform={`scale(${1/sq} ${sq})`}>
   {t==='d'&&<><polygon points={`${-R*.55},${-R*.7} ${-R*.4},${-R*1.15} ${-R*.2},${-R*.8}`} fill='#4b2a8a'/><polygon points={`${R*.55},${-R*.7} ${R*.4},${-R*1.15} ${R*.2},${-R*.8}`} fill='#4b2a8a'/></>}
   <circle r={R} fill={t==='d'?'url(#gV)':'url(#gO)'} stroke={ol} strokeWidth={6}/>
   <ellipse cx={-R*.38} cy={-R*.5} rx={R*.28} ry={R*.14} fill='rgba(255,255,255,.35)' transform={`rotate(-25 ${-R*.38} ${-R*.5})`}/>
   {ojo(-R*.32)}{ojo(R*.32)}
   <circle cx={-R*.56} cy={R*.2} r={R*.11} fill='rgba(255,110,140,.4)'/><circle cx={R*.56} cy={R*.2} r={R*.11} fill='rgba(255,110,140,.4)'/>
   {t==='d'?<g><ellipse cx={0} cy={R*.45} rx={R*.36} ry={R*.06+R*.2*mo*act} fill='#2a1240'/><polygon points={`${-R*.26},${R*.4} ${-R*.14},${R*.4} ${-R*.2},${R*.55}`} fill='#fff'/><polygon points={`${R*.14},${R*.4} ${R*.26},${R*.4} ${R*.2},${R*.55}`} fill='#fff'/></g>
    :<path d={`M${-R*.22} ${R*.34}Q0 ${R*.54} ${R*.22} ${R*.34}`} stroke='#5b3b17' strokeWidth={5} fill='none' strokeLinecap='round'/>}
   {t==='o'&&<g><path d={`M${-R*.82} ${-R*.2}A${R*.82} ${R*.82} 0 0 1 ${R*.82} ${-R*.2}Z`} fill={L} stroke='#9aa800' strokeWidth={5}/><rect x={-R*.95} y={-R*.27} width={R*1.9} height={R*.12} rx={R*.06} fill='#c8dc00' stroke='#9aa800' strokeWidth={3}/><circle cy={-R*.55} r={R*.1} fill='#fff' opacity={.85}/></g>}
  </g>
  {t==='o'&&tool&&<g transform={`translate(${R*.95} ${R*.15}) rotate(${-35+45*Math.sin(s*8+f)*act})`}><line x1={0} y1={0} x2={0} y2={-R*.8} stroke='#7a5a2a' strokeWidth={7} strokeLinecap='round'/><polygon points={`${-R*.25},${-R*.8} ${R*.25},${-R*.8} 0,${-R*1.2}`} fill='#cfd6dd' stroke='#7b8794' strokeWidth={3}/></g>}
 </g>;
};

// Hueso (línea con contorno, brillo y luz interior opcional)
const Hu:React.FC<{x1:number;y1:number;x2:number;y2:number;w:number;c:string;o:string;g?:string}>=({x1,y1,x2,y2,w,c,o,g})=><g strokeLinecap='round'>
 <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={o} strokeWidth={w+8}/>
 <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={c} strokeWidth={w}/>
 <line x1={x1-w*.18} y1={y1} x2={x2-w*.18} y2={y2} stroke='rgba(255,255,255,.4)' strokeWidth={w*.22}/>
 {g&&<line x1={x1} y1={y1} x2={x2} y2={y2} stroke={g} strokeWidth={w*.45}/>}
</g>;

// Esqueleto en lámina 2D. armar 0..1: los huesos vuelan a su sitio.
const Esq:React.FC<{c:string;o:string;armar?:number;g?:string;extra?:React.ReactNode}>=({c,o,armar=1,g='rgba(0,0,0,0)',extra})=>{
 const P=(i:number)=>{const k=Math.max(0,Math.min(1,armar*1.72-i*.09));const u=Math.pow(1-k,3);return `translate(${u*(h(i*3+1)-.5)*1100} ${u*(h(i*5+2)-.5)*1100}) rotate(${u*(h(i*7+3)-.5)*200})`;};
 const rib=(k:number,sg:number)=>`M${sg*10} ${-318+k*42}C${sg*80} ${-352+k*42} ${sg*(150-k*6)} ${-296+k*42} ${sg*(128-k*9)} ${-252+k*42}C${sg*(112-k*8)} ${-232+k*42} ${sg*55} ${-236+k*42} ${sg*22} ${-256+k*42}`;
 const brazo=(sg:number)=><g><circle cx={sg*135} cy={-318} r={26} fill={c} stroke={o} strokeWidth={5}/><Hu x1={sg*135} y1={-318} x2={sg*182} y2={-120} w={22} c={c} o={o}/><Hu x1={sg*182} y1={-112} x2={sg*210} y2={78} w={13} c={c} o={o}/><Hu x1={sg*198} y1={-108} x2={sg*232} y2={74} w={11} c={c} o={o}/><ellipse cx={sg*222} cy={108} rx={22} ry={32} fill={c} stroke={o} strokeWidth={4}/></g>;
 const pierna=(sg:number)=><g><circle cx={sg*62} cy={150} r={32} fill={c} stroke={o} strokeWidth={5}/><Hu x1={sg*62} y1={165} x2={sg*82} y2={428} w={34} c={c} o={o} g={g}/><circle cx={sg*82} cy={442} r={34} fill={c} stroke={o} strokeWidth={5}/><Hu x1={sg*84} y1={466} x2={sg*78} y2={690} w={24} c={c} o={o} g={g}/><Hu x1={sg*104} y1={462} x2={sg*96} y2={690} w={10} c={c} o={o}/><ellipse cx={sg*96} cy={716} rx={52} ry={20} fill={c} stroke={o} strokeWidth={5}/></g>;
 return <g transform='translate(0 -110)'>
  <g transform={P(0)}><ellipse cx={0} cy={-440} rx={72} ry={78} fill={c} stroke={o} strokeWidth={6}/><path d='M-46 -400Q-44 -350 0 -345Q44 -350 46 -400Z' fill={c} stroke={o} strokeWidth={6}/><ellipse cx={-26} cy={-448} rx={17} ry={20} fill='#2a2218'/><ellipse cx={26} cy={-448} rx={17} ry={20} fill='#2a2218'/><path d='M0 -430L-8 -412H8Z' fill='#2a2218'/><path d='M-28 -372H28' stroke='#2a2218' strokeWidth={4}/></g>
  <g transform={P(1)}>{Array.from({length:14}).map((_,j)=><rect key={j} x={-17+j*.3} y={-350+j*32} width={34-j*.5} height={25} rx={9} fill={c} stroke={o} strokeWidth={4}/>)}</g>
  <g transform={P(2)}>{[-1,1].map(sg=>Array.from({length:6}).map((_,k)=><g key={sg+'_'+k} fill='none' strokeLinecap='round'><path d={rib(k,sg)} stroke={o} strokeWidth={19}/><path d={rib(k,sg)} stroke={c} strokeWidth={11}/></g>))}</g>
  <g transform={P(3)}><rect x={-13} y={-310} width={26} height={150} rx={12} fill={c} stroke={o} strokeWidth={5}/><Hu x1={0} y1={-340} x2={-118} y2={-322} w={12} c={c} o={o}/><Hu x1={0} y1={-340} x2={118} y2={-322} w={12} c={c} o={o}/></g>
  <g transform={P(4)}>{brazo(-1)}</g><g transform={P(5)}>{brazo(1)}</g>
  <g transform={P(6)}><path d='M-120 70Q-170 110 -140 190Q-100 230 -62 200L0 160L62 200Q100 230 140 190Q170 110 120 70Q60 50 0 90Q-60 50 -120 70Z' fill={c} stroke={o} strokeWidth={6}/><ellipse cx={0} cy={118} rx={24} ry={20} fill={o} opacity={.4}/></g>
  <g transform={P(7)}>{pierna(-1)}</g><g transform={P(8)}>{pierna(1)}</g>
  {extra}
 </g>;
};

// Placa de hueso (lámina médica crema con trabéculas y huecos rosados)
const Placa:React.FC<{sem:number;corteza?:boolean}>=({sem,corteza=false})=><g>
 <rect x={-600} y={-300} width={2400} height={2700} fill={CREMA}/>
 {Array.from({length:34}).map((_,i)=><path key={i} d={`M${h(i+sem)*1180-50} ${h(i+sem+50)*2100-100}Q${h(i+sem+9)*1180} ${h(i+sem+19)*2100} ${h(i+sem+29)*1180} ${h(i+sem+39)*2100}`} stroke={i%3?'#e6c79c':'#fff7e4'} strokeWidth={8+h(i*3+sem)*20} fill='none' strokeLinecap='round' opacity={.85}/>)}
 {Array.from({length:22}).map((_,i)=><ellipse key={i} cx={h(i*2+sem+3)*1100} cy={h(i*5+sem+7)*2000} rx={26+h(i+sem)*60} ry={20+h(i*3+sem)*45} fill='#efb3ae' opacity={.5}/>)}
 {corteza&&<g><rect x={-600} y={-300} width={680} height={2700} fill='#d3b685'/><rect x={1000} y={-300} width={800} height={2700} fill='#d3b685'/><path d='M80 -300V2400M1000 -300V2400' stroke='#a98a58' strokeWidth={10}/>{Array.from({length:18}).map((_,i)=><path key={i} d={`M${-560+h(i)*620} ${-200+i*150}H${-300+h(i+3)*360}M${1040+h(i+5)*620} ${-150+i*150}H${1200+h(i+7)*500}`} stroke='#b99a68' strokeWidth={7} strokeLinecap='round'/>)}</g>}
</g>;

// Túnel (dig 0..1 cavado; fill 0..1 relleno con ladrillos de hueso nuevo)
const TP:[number,number][]=[[100,620],[430,860],[470,1200],[790,1380],[980,1640]];
const TD='M100 620L430 860L470 1200L790 1380L980 1640';
const LT=TP.slice(1).reduce((a,p,i)=>a+Math.hypot(p[0]-TP[i][0],p[1]-TP[i][1]),0);
const Tunel:React.FC<{dig:number;fill:number}>=({dig,fill})=>{
 const n=fill*LT/56;const fl=Math.floor(n);const fr=n-fl;
 const arr:string[]=[];for(let i=0;i<fl;i++)arr.push('46','10');if(fr>0.02){arr.push(String(Math.max(1,46*Math.min(1,fr*1.3))),'99999');}else arr.push('0','99999');
 const da=arr.join(' ');
 return <g fill='none' strokeLinejoin='round'>
  <path d={TD} stroke='#8a3a4f' strokeWidth={176} strokeLinecap='round' strokeDasharray={`${dig*LT} ${LT*2}`}/>
  <path d={TD} stroke='#4b1a2e' strokeWidth={146} strokeLinecap='round' strokeDasharray={`${dig*LT} ${LT*2}`}/>
  {fill>0&&<><path d={TD} stroke='#cdb27d' strokeWidth={146} strokeLinecap='butt' strokeDasharray={da}/><path d={TD} stroke={HUE} strokeWidth={128} strokeLinecap='butt' strokeDasharray={da}/><path d={TD} stroke='rgba(231,255,0,.55)' strokeWidth={14} strokeLinecap='butt' strokeDasharray={da}/></>}
 </g>;
};

// ---------- sitios ----------
const Sc0:React.FC<{s:number}>=({s})=>{
 const sw=q(s,.1,2.05);const X=100+sw*880;
 return <g>
  {Array.from({length:26}).map((_,i)=>{const x=((i*90-s*260)%2340+2340)%2340-300;return <g key={i}><line x1={x} y1={1745} x2={x} y2={1745+(i%5===0?44:24)} stroke='rgba(231,255,0,.6)' strokeWidth={5}/>{i%5===0&&<text x={x} y={1830} opacity={Math.max(0,Math.min(1,(x-260)/80,(820-x)/80))} fill='rgba(255,255,255,.6)' fontSize={34} fontWeight={800} fontFamily={FONT} textAnchor='middle'>{'AÑO '+((i/5|0)%10)}</text>}</g>;})}
  <line x1={-300} y1={1745} x2={1400} y2={1745} stroke='rgba(231,255,0,.6)' strokeWidth={5}/>
  <g transform='translate(540 1010) scale(.95)'><Esq c={VIE} o={OUT}/></g>
  <clipPath id='nuevo0'><rect x={-600} y={0} width={X+600} height={2000}/></clipPath>
  <g clipPath='url(#nuevo0)'><g transform='translate(540 1010) scale(.95)'><Esq c={HUE} o={OUT}/></g></g>
  <rect x={X-5} y={300} width={10} height={1450} fill={L}/><rect x={X-40} y={300} width={80} height={1450} fill={L} opacity={.18}/>
  {Array.from({length:14}).map((_,i)=><circle key={i} cx={X+Math.sin(s*7+i*3)*50} cy={420+((i*190+s*400)%1300)} r={5+h(i)*6} fill={L} opacity={.7}/>)}
 </g>;
};
const Sc1:React.FC<{s:number}>=({s})=>{
 const tv=en('vivo');const rk=q(s,tv,tv+.7);const bt=s>tv?beat(s):0;
 const grietas=['M0 -370L-18 -300L12 -250L-10 -190L20 -130L-6 -60L14 20','M80 -330L110 -250L90 -200L118 -140','M70 170L96 250L72 320L98 400','M-70 190L-92 270L-70 340L-88 410','M10 -510L-8 -470L14 -430L0 -400','M-150 -310L-176 -240L-150 -180'];
 const cr=<g fill='none' strokeLinecap='round' strokeLinejoin='round'>{grietas.map((d,i)=>{const p=q(s,tv+i*.07,tv+i*.07+.4);return <g key={i} opacity={p>0?1:0}><path d={d} pathLength={1} stroke='#17101a' strokeWidth={9} strokeDasharray='1 1' strokeDashoffset={1-p}/><path d={d} pathLength={1} stroke={ROS} strokeWidth={4} strokeDasharray='1 1' strokeDashoffset={1-p}/></g>;})}</g>;
 return <g>
  {Array.from({length:30}).map((_,i)=>{const t=(s*.7+h(i)*3)%2;return <circle key={i} cx={100+h(i+1)*880} cy={560+t*500} r={3+h(i*2)*5} fill='#b5b8bd' opacity={.5*(1-t/2)}/>;})}
  <g transform={`translate(540 1010) scale(${.95*(1+.025*bt)})`}>
   <rect x={-210} y={625} width={420} height={80} rx={12} fill='#6c6f75' stroke='#2f3136' strokeWidth={6}/><text x={0} y={680} textAnchor='middle' fill='#3f4146' fontSize={34} fontWeight={800} fontFamily={FONT}>PARA SIEMPRE</text>
   <Esq c={PIE} o='#2f3136' g={`rgba(255,111,145,${rk*(.55+.45*bt)})`} extra={cr}/>
  </g>
  {rk>0&&<Luz x={540} y={1050} r={330} color={`rgba(255,111,145,${.4*rk*(.5+.5*bt)})`}/>}
 </g>;
};
const Sc2:React.FC<{s:number}>=({s})=>{
 const k=q(s,6.7,en('equipos'));const sh=q(s,6.7,en('equipos'));const tE=en('equipos');
 const D:[number,number][]=[[210,1000],[140,1240],[300,1400]],O:[number,number][]=[[880,1010],[790,1230],[900,1420]];
 const tg=spr0(s,tE);
 return <g>
  <Placa sem={3} corteza/>
  {[[300,1110],[780,1090]].map(([x,y],i)=><circle key={i} cx={x} cy={y} r={170+Math.sin(s*3+i)*14} fill={i?'rgba(231,255,0,.09)':'rgba(142,91,224,.16)'}/>)}
  {D.map(([x,y],i)=><Cel key={'d'+i} t='d' s={s} x={x-(1-sh)*420+Math.sin(s*4+i)*10} y={y} r={66} f={i*1.7} act={1}/>)}
  {O.map(([x,y],i)=><Cel key={'o'+i} t='o' s={s} x={x+(1-sh)*420-Math.sin(s*4+i)*10} y={y} r={66} f={i*1.3+.5} hero={i===1} act={1}/>)}
  <path d={`M${400+Math.sin(s*6)*20} 1100H${540+Math.sin(s*6)*30}M${690-Math.sin(s*6)*20} 1100H${560-Math.sin(s*6)*30}`} stroke={L} strokeWidth={10} strokeLinecap='round' opacity={k>.95?1:0}/>
  <Tag x={350} y={830} k={tg} width={360} color='#c4a4ff' size={34}>DEMOLEDORAS</Tag>
  <Tag x={800} y={830} k={tg} width={400} color={L} size={34}>CONSTRUCTORAS</Tag>
  {Array.from({length:18}).map((_,i)=>{const t=(s*.5+h(i)*4)%3;return <circle key={i} cx={120+h(i*3)*840} cy={1650-t*620} r={5+h(i)*7} fill='#ffd2cc' opacity={.55*(1-t/3)}/>;})}
 </g>;
};
const spr0=(s:number,t:number)=>Math.min(1.08,Math.max(0,(s-t)/.35))*(s>t?1:0);
const Sc3:React.FC<{s:number}>=({s})=>{
 const t0=A[3]+.3,t1=en('túneles')+.2;const hd=enCamino(s,TP,t0,t1);
 return <g>
  <Placa sem={11}/>
  <Tunel dig={hd.p} fill={0}/>
  {Array.from({length:26}).map((_,j)=>{const ts=t0+j*.1;const age=s-ts;if(age<0||age>1.1)return null;const p=enCamino(ts,TP,t0,t1);return <polygon key={j} points='0,-12 14,6 -12,10' fill={j%2?'#e4cfa3':'#c9ab78'} transform={`translate(${p.x+(h(j)-.5)*130+age*(h(j+2)-.5)*120} ${p.y+(h(j+4)-.5)*60-60*age+520*age*age}) rotate(${age*400*(h(j)-.5)})`} opacity={1-age/1.1}/>;})}
  {[[-90,-20],[-40,70],[-130,60]].map(([dx,dy],i)=><Cel key={i} t='d' s={s} x={hd.x+dx} y={hd.y+dy} r={64} f={i*1.4} act={1}/>)}
  <Tag x={540} y={560} k={spr0(s,en('túneles'))} width={420} color='#c4a4ff' size={40}>TÚNEL ABIERTO</Tag>
 </g>;
};
const tF=en('rellenan'),tEnd=en('nuevo',2)+.1;
const Sc4:React.FC<{s:number}>=({s})=>{
 const fp=enCamino(s,TP,tF,tEnd);const run=q(s,A[4],A[4]+1.9);
 const team=[0,1,2].map(k=>{const p=enCamino(s-k*.4,TP,tF,tEnd);return {x:p.x-(1-run)*520-k*10,y:p.y+(k-1)*55};});
 const dm=[0,1].map(k=>enCamino(s+.9+k*.25,TP,tF,tEnd));
 return <g>
  <Placa sem={17}/>
  <Tunel dig={1} fill={fp.p}/>
  {dm.map((p,k)=><Cel key={'d'+k} t='d' s={s} x={p.x+30} y={p.y-20+k*50} r={54} f={k*2} act={1}/>)}
